{
  "arguments": [
    {
      "claim": "The threat or use of nuclear weapons violates Article 8 (iv) of the Rome Statute because it inevitably causes widespread, long‑term and severe damage to the natural environment that is clearly excessive in relation to any concrete and direct military advantage, even in an existential self‑defence scenario.",
      "reasoning": "Article 8 (iv) criminalises any attack launched with knowledge that it will cause such environmental damage that is clearly excessive compared with the anticipated military advantage. Nuclear detonations produce indiscriminate, far‑reaching radiation, blast and fire that devastate ecosystems for generations, far outweighing any specific tactical gain. Consequently, any threatened or actual use of nuclear weapons fails the proportionality test embedded in 8 (iv) and constitutes a war crime.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(b)(iv)",
          "quoted_text": "Intentionally launching an attack in the knowledge that such attack will cause incidental loss of life or injury to civilians or damage to civilian objects or widespread, long-term and severe damage to the natural environment which would be clearly excessive in relation to the concrete and direct overall military advantage anticipated;"
        }
      ]
    },
    {
      "claim": "Nuclear weapons are inherently indiscriminate and cause superfluous injury or unnecessary suffering, thereby breaching Article 8 (xx) of the Rome Statute.",
      "reasoning": "Article 8 (xx) prohibits the employment of weapons whose nature is to cause superfluous injury, unnecessary suffering, or that are inherently indiscriminate. The immense blast radius, thermal effects, and lingering radiation of nuclear weapons cannot be limited to combatants or military objectives; they affect civilians and the environment indiscriminately. Their use therefore falls squarely within the prohibited category of weapons under 8 (xx).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(b)(xx)",
          "quoted_text": "Employing weapons, projectiles and material and methods of warfare which are of a nature to cause superfluous injury or unnecessary suffering or which are inherently indiscriminate in violation of the international law of armed conflict, provided that such weapons, projectiles and material and methods of warfare are the subject of a comprehensive prohibition and are included in an annex to this Statute, by an amendment in accordance with the relevant provisions set forth in articles 121   and 123 ;"
        }
      ]
    },
    {
      "claim": "The use of nuclear weapons inevitably constitutes an intentional attack against civilian objects, contravening Article 8 (b)(ii) of the Rome Statute.",
      "reasoning": "Article 8 (b)(ii) criminalises intentional attacks against civilian objects—objects that are not military objectives. Nuclear detonations cannot be confined to a purely military target; the blast, heat, and radiation indiscriminately affect hospitals, schools, infrastructure, and natural resources, all of which are civilian objects. Hence any nuclear strike, regardless of the intended target, amounts to an intentional attack on civilian objects and breaches 8 (b)(ii).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(b)(ii)",
          "quoted_text": "Intentionally directing attacks against civilian objects, that is, objects which are not military objectives;"
        }
      ]
    },
    {
      "claim": "Even when aimed at a legitimate military objective, nuclear weapons cannot satisfy the precautionary requirements of CCW Protocol III, article 2(3), and therefore are unlawful.",
      "reasoning": "Protocol III, article 2(3) prohibits attacks on military objectives located within concentrations of civilians by means of weapons that cannot be precisely controlled, unless the objective is clearly separated and all feasible precautions are taken to minimise civilian harm. Nuclear weapons are incapable of being limited to a single target or of ensuring separation from civilian concentrations; their effects are inherently uncontrollable and indiscriminate. Consequently, any nuclear strike would breach the precautionary standard set out in 2(3), rendering its use unlawful under customary IHL incorporated by reference in the CCW.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ccw_p_iii",
          "article": "2(3)",
          "quoted_text": "It is further prohibited to make any military objective located within a concentration of civilians the object of attack by means of incendiary weapons other than air-delivered incendiary weapons, except when such military objective is clearly separated from the concentration of civilians and all feasible precautions are taken with a view to limiting the incendiary effects to the military objective and to avoiding, and in any event to minimizing, incidental loss of civilian life, injury to civilians and damage civilian objects."
        }
      ]
    },
    {
      "claim": "The environmental and humanitarian consequences of nuclear weapons amount to a prohibited attack on objects indispensable to civilian survival under Additional Protocol I, article 54(2).",
      "reasoning": "Article 54(2) bans attacks on objects essential for civilian survival—such as water, food, and agricultural resources—when the purpose is to deny those objects to the civilian population. Nuclear detonations contaminate water sources, destroy crops, and render land uninhabitable for generations, effectively attacking objects indispensable to civilian life. Even if the stated purpose is self‑defence, the effect is the same: the denial of essential sustenance to the civilian population, which is prohibited by 54(2).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "54",
          "quoted_text": "It is prohibited to attack, destroy, remove or render useless objects indispensable to the survival of the civilian population, such as foodstuffs, agricultural areas for the production of foodstuffs, crops, livestock, drinking water installations and supplies and irrigation works, for the specific purpose of denying them for their sustenance value to the civilian population or the adverse Party, whatever the motive, whether in order to starve out civilians, to cause them to move away, or for any other motive."
        }
      ]
    }
  ]
}

